using System;using System.IO;using System.Diagnostics;using System.Linq;using System.Runtime.InteropServices;using System.Text;using System.Text.RegularExpressions;using System.Threading;using System.Runtime.CompilerServices;
internal static class BootDiagnostics {
 internal static string LastPath;static readonly object Sync=new object();
 internal static string Clean(string text){return Regex.Replace(text??"",@"sk-[A-Za-z0-9_-]+|(?i)(Bearer\s+)[^\s]+|(?i)((?:token|ticket|api[_-]?key)=)[^\s&]+","[redacted]");}
 static string Folder(){string root=AppDomain.CurrentDomain.BaseDirectory,arg=Environment.GetCommandLineArgs().FirstOrDefault(x=>x.StartsWith("--data=",StringComparison.OrdinalIgnoreCase)),data=arg==null?Environment.GetEnvironmentVariable("FIREFLY_DATA_DIR"):arg.Substring(7).Trim('"');if(String.IsNullOrWhiteSpace(data)){string pointer=Path.Combine(root,"user-data-location.txt");if(File.Exists(pointer))data=File.ReadAllText(pointer).Trim();}if(!String.IsNullOrWhiteSpace(data)&&Path.IsPathRooted(data))return Path.Combine(data,"logs");return Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"FireflyGift","Diagnostics");}
 internal static void Record(string stage,string details){try{lock(Sync){string folder=Folder();Directory.CreateDirectory(folder);LastPath=Path.Combine(folder,"startup.log");File.AppendAllText(LastPath,DateTime.UtcNow.ToString("o")+" pid="+Process.GetCurrentProcess().Id+" stage="+stage+" "+Clean(details).Replace('\r',' ').Replace('\n',' ')+Environment.NewLine,Encoding.UTF8);}}catch{}}
 [DllImport("user32.dll")]static extern IntPtr GetProcessWindowStation();[DllImport("user32.dll")]static extern IntPtr GetThreadDesktop(uint id);[DllImport("kernel32.dll")]static extern uint GetCurrentThreadId();
 [DllImport("user32.dll",CharSet=CharSet.Unicode)]static extern bool GetUserObjectInformation(IntPtr handle,int index,StringBuilder data,int length,out int needed);
 [DllImport("advapi32.dll",SetLastError=true)]static extern bool OpenProcessToken(IntPtr process,uint access,out IntPtr token);
 [DllImport("advapi32.dll",SetLastError=true)]static extern bool GetTokenInformation(IntPtr token,int info,IntPtr output,int size,out int needed);
 [DllImport("advapi32.dll")]static extern IntPtr GetSidSubAuthorityCount(IntPtr sid);[DllImport("advapi32.dll")]static extern IntPtr GetSidSubAuthority(IntPtr sid,uint index);[DllImport("kernel32.dll")]static extern bool CloseHandle(IntPtr h);
 static string ObjectName(IntPtr handle){try{var b=new StringBuilder(256);int needed;return GetUserObjectInformation(handle,2,b,512,out needed)?b.ToString():"unknown";}catch{return "unknown";}}
 static string Integrity(){IntPtr token;if(!OpenProcessToken(Process.GetCurrentProcess().Handle,8,out token))return "unknown";try{int n;GetTokenInformation(token,25,IntPtr.Zero,0,out n);IntPtr p=Marshal.AllocHGlobal(n);try{if(!GetTokenInformation(token,25,p,n,out n))return "unknown";IntPtr sid=Marshal.ReadIntPtr(p);byte count=Marshal.ReadByte(GetSidSubAuthorityCount(sid));int rid=Marshal.ReadInt32(GetSidSubAuthority(sid,(uint)(count-1)));return rid.ToString("X");}finally{Marshal.FreeHGlobal(p);}}finally{CloseHandle(token);}}
 internal static void Entry(){Record("entry","exe="+Environment.GetCommandLineArgs()[0]+" cwd="+Environment.CurrentDirectory+" version="+typeof(BootDiagnostics).Assembly.GetName().Version+" session="+Process.GetCurrentProcess().SessionId+" interactive="+Environment.UserInteractive+" station="+ObjectName(GetProcessWindowStation())+" desktop="+ObjectName(GetThreadDesktop(GetCurrentThreadId()))+" integrityRID="+Integrity());}
}
internal static class EntryPoint {
 [STAThread]static int Main(string[] args){BootDiagnostics.Entry();AppDomain.CurrentDomain.UnhandledException+=(s,e)=>BootDiagnostics.Record("unhandled",Convert.ToString(e.ExceptionObject));int code=9;try{code=Invoke(args);return code;}catch(Exception e){BootDiagnostics.Record("startup-failed",e.ToString());try{System.Windows.Forms.MessageBox.Show("流萤暂时没能打开，原有资料没有改动。\n请重试；启动记录已保存在：\n"+BootDiagnostics.LastPath,"流萤");}catch{}return code;}finally{BootDiagnostics.Record("exit","code="+code);}}
 [MethodImpl(MethodImplOptions.NoInlining)]static int Invoke(string[] args){return FireflyApp.Run(args);}
}
